
const langs = {
 ar:"العربية",en:"English",fr:"Français",de:"Deutsch",es:"Español",
 it:"Italiano",ru:"Русский",zh:"中文",tr:"Türkçe",hu:"Magyar",bg:"Български"
};
const ministryUrl="https://www.mota.gov.jo/Ar/Pages/الهيكل_التنظيمي";
const officialServices="https://www.tourism.jo/Default/Ar";
let current="ar";
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
function value(path){
 const parts = path.replace(/\\[(\\d+)\\]/g, ".$1").split(".");
 const selected=parts.reduce((o,k)=>o?.[k],window.MADABA_I18N[current]);
 if(selected!==undefined && selected!==null) return selected;
 return parts.reduce((o,k)=>o?.[k],window.MADABA_I18N.en) ?? "";
}
function renderLanguageBar(){
 const bar=$("#languageBar"); if(!bar)return;
 bar.innerHTML=Object.entries(langs).map(([code,label])=>`<button type="button" class="language-option" data-language="${code}" lang="${code}" aria-pressed="${code===current}" title="${label}">${label}</button>`).join("");
}
function setLanguage(lang){
 if(!window.MADABA_I18N[lang]) lang="ar";
 current=lang; localStorage.setItem("madaba-directorate-lang",lang); document.title=(window.MADABA_I18N[lang]?.name||"Madaba Tourism Directorate");
 const d=window.MADABA_I18N[lang]; document.documentElement.lang=lang; document.documentElement.dir=d.dir||"ltr";
 $("#languageBar")?.querySelectorAll("[data-language]").forEach(button=>{
   const active=button.dataset.language===lang;button.classList.toggle("active",active);button.setAttribute("aria-pressed",String(active));
 });
 $$("[data-i]").forEach(el=>{
   const v=value(el.dataset.i);
   if(typeof v==="string") el.textContent=v;
   else if(Array.isArray(v)) el.textContent=v.join(" · ");
 });
 renderNav(); renderDynamic(); renderAbout(); renderLegal(); renderMovies(); $$(`[data-i-aria]`).forEach(el=>el.setAttribute("aria-label",value(el.dataset.iAria))); $$(`[data-i-alt]`).forEach(el=>el.setAttribute("alt",value(el.dataset.iAlt))); $$(`[data-i-title]`).forEach(el=>el.setAttribute("title",value(el.dataset.iTitle))); const meta=document.querySelector(`meta[name="description"]`); if(meta)meta.content=value("meta_description"); if(window.MADABA_MAP_DATA) renderMapInterface();
}
function renderNav(){
 const nav=$("#mainNav"); nav.innerHTML="";
 const pages=["home","about","visit","professions","services","location","contact","complaints","legal","map","movies"];
 value("nav").forEach((label,i)=>{
   const b=document.createElement("button");b.type="button";b.textContent=label;b.dataset.go=pages[i];
   if(pages[i]===getPage())b.classList.add("active");nav.appendChild(b);
 });
}
function getPage(){return $(".page.active")?.id||"home"}
function go(id){
 const page=id==="location"?"location":id;
 $$(".page").forEach(p=>p.classList.toggle("active",p.id===page));
 $$("#mainNav button").forEach(b=>b.classList.toggle("active",b.dataset.go===page));
 $("#mainNav").classList.remove("open");
 window.scrollTo({top:0,behavior:"smooth"});
 if(page==="location") setTimeout(initMaps,120);
 if(page==="map") setTimeout(initMaps,160);
}
function renderMovies(){
 const grid=$("#moviesGrid"); if(!grid)return;
 const d=window.MADABA_I18N[current];
 const movies=[
  {id:"z8gVhugX03o",title:d.movie_1||"Movie 1"},
  {id:"U2Q36HTDyY8",title:d.movie_2||"Movie 2"},
  {id:"4Kkh7K1ejks",title:d.movie_3||"Movie 3"}
 ];
 grid.innerHTML=movies.map((m,i)=>`<article class="movie-card"><div class="movie-media" id="movie-media-${i}"><button type="button" class="movie-poster" data-play-movie="${m.id}" data-movie-index="${i}" aria-label="${d.movie_play||"Play video"}: ${m.title}"><img src="https://img.youtube.com/vi/${m.id}/hqdefault.jpg" alt="${m.title}" loading="lazy" onerror="this.src='https://img.youtube.com/vi/${m.id}/mqdefault.jpg'"><span class="movie-play-icon" aria-hidden="true">▶</span><span class="movie-play-label">${d.movie_play||"Play video"}</span></button></div><div class="movie-copy"><h2>${m.title}</h2><a class="movie-youtube-link" href="https://www.youtube.com/watch?v=${m.id}" target="_blank" rel="noopener noreferrer">${d.movie_youtube||"Open on YouTube"} ↗</a></div></article>`).join("");
}
function renderDynamic(){
 const d=window.MADABA_I18N[current];
 const churchUrl="https://www.google.com/maps/search/?api=1&query=St+George%27s+Church+Madaba+Jordan";
 $("#placeGrid").innerHTML=d.sites.map((s,i)=>`<li class="place-card"><div class="symbol">✦ ${String(i+1).padStart(2,"0")}</div><h3>${s}</h3><a class="text-link" href="${i===1?churchUrl:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s+" Madaba Jordan")}`}" target="_blank" rel="noopener">${i===1?d.map_site_link:d.map_open}</a></li>`).join("");
 const professionItems=[
 [d.profession_opportunity,"https://mota.gov.jo/AR/List/فرص_استثمارية"],
 [d.profession_providers,"https://mota.gov.jo/AR/List/قائمة_مقدمي_الخدمة"],
 [d.profession_guides,"https://mota.gov.jo/Ar/Pages/تأهيل_الأدلاء_السياحيين"],
 [d.profession_associations,"https://mota.gov.jo/AR/List/الجمعيات__المتخصصة"],
 [d.profession_classification,"https://mota.gov.jo/Ar/List/تصنيف_المنشأة"]
 ];
 $("#professionGrid").innerHTML=professionItems.map(([s,u])=>`<article class="profession-card"><div class="symbol">▤</div><h3>${s}</h3><p>${d.official_ministry_content}</p><a class="text-link" href="${u}" target="_blank" rel="noopener">${d.open_official_content} ↗</a></article>`).join("");
 const services=[
 ["service_card_1","https://mota.gov.jo/EBV4.0/Root_Storage/AR/EB_List_Page/اضافة_لغة_للدليل_السياحي.pdf"],
 ["service_card_2","https://mota.gov.jo/AR/List/بطاقات__الخدمات"],
 ["service_card_3","https://mota.gov.jo/EBV4.0/Root_Storage/AR/EB_List_Page/تجديد_رخصة_دليل_سياحي.pdf"],
 ["service_card_4","https://mota.gov.jo/EBV4.0/Root_Storage/AR/EB_List_Page/ترخيص_دليل_سياحي_لأول_مرة_1.pdf"],
 ["service_card_5","https://mota.gov.jo/AR/List/بطاقات__الخدمات"],
 ["service_card_6","https://mota.gov.jo/AR/List/بطاقات__الخدمات"],
 ["service_card_7","https://mota.gov.jo/EBV4.0/Root_Storage/AR/EB_List_Page/طلب_تصاريح_مؤقتة_(مرافقة_سياح).pdf"],
 ["service_card_8","https://www.mota.gov.jo/EBV4.0/Root_Storage/AR/EB_List_Page/طلب_إعادة_تأهيل_أو_تطوير_مبنى_تراثي.pdf"],
 ["service_card_9","https://mota.gov.jo/AR/List/بطاقات__الخدمات"],
 ["service_card_10","https://mota.gov.jo/AR/List/بطاقات__الخدمات"],
 ["service_card_11","https://mota.gov.jo/EBV4.0/Root_Storage/AR/EB_List_Page/طلب_تعديل_درجة_أو_فئة_التصنيف_أو_اضافة_مرفق.pdf"],
 ];
 $("#serviceGrid").innerHTML=services.map(([key,u])=>{const direct=u.toLowerCase().endsWith(".pdf");const title=value(key);const desc=direct?value("service_pdf_description"):value("service_listing_description");const link=direct?value("service_pdf_open"):value("service_listing_open");return `<article class="service-card"><div class="symbol">◎</div><h3>${title}</h3><p>${desc}</p><a class="text-link" href="${u}" target="_blank" rel="noopener">${link}</a></article>`}).join("");
 const mapUrl="https://www.google.com/maps/search/?api=1&query=Madaba+Tourism+Directorate";
 $("#contactGrid").innerHTML=`
  <article class="contact-item"><b>${d.phone}</b><a href="tel:053245527" dir="ltr">053245527</a></article>
  <article class="contact-item"><b>${d.email}</b><a href="mailto:Madaba@mota.gov.jo" dir="ltr">Madaba@mota.gov.jo</a></article>
  <article class="contact-item"><b>${d.address}</b><a href="${mapUrl}" target="_blank" rel="noopener noreferrer">${d.contact_address_value}<span class="contact-map-link">${d.contact_map} ↗</span></a></article>
  <article class="contact-item"><b>${d.hours}</b><span><strong>${d.contact_hours_weekdays}</strong><br>${d.contact_hours_weekdays_time}<br><strong>${d.contact_hours_weekend}</strong><br>${d.contact_hours_closed}</span></article>`;
 $("#googleDirections").href=mapUrl;
}
