let legalFilter=-1;
function renderLegal(){const t=legalUi[current]||legalUi.en;if(!document.getElementById('legalResults'))return;document.querySelectorAll('[data-legal-ui]').forEach(el=>{const k=el.dataset.legalUi;el.textContent=t[k]||legalUi.en[k]||'';});$('#legalSearch').placeholder=t.searchPlaceholder;const sel=$('#legalCategory');const old=sel.value;sel.innerHTML=`<option value="-1">${t.all}</option>`+t.category.map((x,i)=>`<option value="${i}">${x}</option>`).join('');sel.value=old||'-1';const tabs=$('#legalCategories');tabs.innerHTML=`<button class="legal-category-btn ${legalFilter===-1?'active':''}" data-legal-filter="-1">${t.all}</button>`+t.category.map((x,i)=>`<button class="legal-category-btn ${legalFilter===i?'active':''}" data-legal-filter="${i}">${x}</button>`).join('');const official=['https://mota.gov.jo/AR/Pages/الدستور_الاردني','https://www.mota.gov.jo/Ar/List/القوانين','https://www.mota.gov.jo/Ar/List/الانظمة','https://www.mota.gov.jo/AR/List/التعليمات','https://www.mota.gov.jo/Ar/List/القرارات','https://www.mota.gov.jo/AR/List/التشاور_الالكتروني_حول_التشريعات'];$('#legalOfficialLinks').innerHTML=official.map((u,i)=>`<a href="${u}" target="_blank" rel="noopener">${t.category[i]} · ${t.officialList} ↗</a>`).join('');drawLegalResults();}
function drawLegalResults(){const t=legalUi[current]||legalUi.en,q=($('#legalSearch')?.value||'').trim().toLocaleLowerCase();const c=legalFilter;const names=legalNameTranslations[current]||legalNameTranslations.en;const list=legalData.map((x,i)=>({...x,displayName:names[i]||x.name})).filter(x=>(c<0||x.cat===c)&&(!q||x.name.toLocaleLowerCase().includes(q)||x.displayName.toLocaleLowerCase().includes(q)));$('#legalResults').innerHTML=list.length?list.map(x=>{const size=x.size==='مسودة تشاور'?({ar:'مسودة تشاور',en:'Consultation draft',fr:'Projet soumis à consultation',de:'Konsultationsentwurf',es:'Borrador para consulta',it:'Bozza in consultazione',ru:'Проект для консультации',zh:'征求意见稿',tr:'Görüş taslağı',hu:'Konzultációs tervezet',bg:'Проект за консултация'}[current]||'Consultation draft'):x.size.replace('ك.ب','KB').replace(' ك.ب',' KB');return `<article class="legal-card"><h3>${x.displayName}</h3><div class="legal-meta">${t.category[x.cat]} · ${t.size}: ${size}</div><div class="legal-actions">${x.url?`<a href="${x.url}" target="_blank" rel="noopener">${t.view} ↗</a>`:''}<a href="${x.source}" target="_blank" rel="noopener">${t.openOfficial} ↗</a></div></article>`}).join(''):`<div class="legal-empty">${t.noResults}</div>`;$('#legalCategories').querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.legalFilter)===legalFilter));}
document.addEventListener('input',e=>{if(e.target.id==='legalSearch')drawLegalResults();});document.addEventListener('change',e=>{if(e.target.id==='legalCategory'){legalFilter=Number(e.target.value);renderLegal();}});document.addEventListener('click',e=>{const b=e.target.closest('[data-legal-filter]');if(b){legalFilter=Number(b.dataset.legalFilter);$('#legalCategory').value=String(legalFilter);renderLegal();}});
function renderAbout(){
 const d=window.MADABA_ABOUT?.[current]||window.MADABA_ABOUT?.en; if(!d)return;
 $$('[data-about]').forEach(el=>{const v=d[el.dataset.about];if(typeof v==='string')el.textContent=v;});
 const tabs=$('#aboutTabs'); tabs.innerHTML='';
 const ids=['overview','vision','values','structure','tasks'];
 d.tabs.forEach((label,i)=>{const b=document.createElement('button');b.type='button';b.className='about-tab'+(i===0?' active':'');b.textContent=label;b.dataset.aboutTarget=ids[i];tabs.appendChild(b);});
 $('#awardsGrid').innerHTML=d.awards.map(([year,title])=>`<article class="award-card"><span class="award-year">${year}</span><h3>${title}</h3><span class="award-mark">✦</span></article>`).join('');
 $('#valuesGrid').innerHTML=d.values.map((v,i)=>`<article class="value-card"><span>${['◇','✦','◎','◈','✧','⌖'][i]}</span><b>${v}</b></article>`).join('');
 const departments=d.departments.map((name,i)=>`<article class="org-department"><h3>${name}</h3>${d.heads[i]?`<p class="org-head">${d.heads[i]}</p>`:''}<ul>${d.staff[i].map(n=>`<li>${n}</li>`).join('')}</ul></article>`).join('');
 $('#orgChart').innerHTML=`<div class="org-director"><small>${d.director}</small><strong>${d.directorName||"Wael Janineh"}</strong></div><div class="org-connector"></div><div class="org-departments">${departments}</div>`;
 $('#tasksGrid').innerHTML=d.tasks.map((t,i)=>`<article class="task-card"><span>${String(i+1).padStart(2,'0')}</span><p>${t}</p></article>`).join('');
}
let madabaInteractiveMap=null;
let madabaMarkers=[];
const mapLocationsCache={};
function mapText(key){const m=window.MADABA_MAP_DATA;return m.ui[current]?.[key]||m.ui.en[key]||key;}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function mapGoogleUrl(name){return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(name+', Madaba Governorate, Jordan');}
function mapCategoryName(idx){const m=window.MADABA_MAP_DATA;return (m.cats[current]||m.cats.en)[idx]||(m.cats.en[idx]||'');}
function renderMapInterface(){
 const m=window.MADABA_MAP_DATA;if(!m||!$('#mapCategory'))return;
 madabaMarkers.forEach(({index,marker})=>marker.setPopupContent(`<strong>${esc(m.names[current][index])}</strong><br><a href="${mapGoogleUrl(m.queries[index])}" target="_blank" rel="noopener">${esc(mapText('directions'))}</a>`));
 const cat=$('#mapCategory'),old=cat.value||'0';
 cat.innerHTML=(m.cats[current]||m.cats.en).map((v,i)=>`<option value="${i}">${esc(v)}</option>`).join('');cat.value=old;
 $('#mapSearch').placeholder=mapText('searchPlaceholder');
 $('[data-map-ui="brochureTitle"]').textContent=mapText('brochureTitle');
 $('[data-map-ui="interactiveTitle"]').textContent=mapText('interactiveTitle');
 $('[data-map-ui="interactiveDesc"]').textContent=mapText('interactiveDesc');
 $('[data-map-ui="searchLabel"]').textContent=mapText('searchLabel');
 $('[data-map-ui="categoryLabel"]').textContent=mapText('categoryLabel');
 $('[data-map-ui="accuracyNote"]').textContent=mapText('accuracyNote');
 renderMapSiteList();
}
function renderMapSiteList(){
 const m=window.MADABA_MAP_DATA;if(!m||!$('#mapSiteList'))return;
 const q=$('#mapSearch').value.trim().toLocaleLowerCase();const c=Number($('#mapCategory').value||0);
 const filtered=m.names[current].map((name,i)=>({name,i})).filter(({name,i})=>(!c||m.categories[i]===c)&&(!q||name.toLocaleLowerCase().includes(q)||m.names.en[i].toLowerCase().includes(q)));
 $('#mapSiteCount').textContent=`${filtered.length} / ${m.names.en.length}`;
 $('#mapSiteList').innerHTML=filtered.map(({name,i})=>`<button type="button" class="map-site-row" data-map-site="${i}"><span class="map-site-number">${i+1}</span><span class="map-site-row-copy"><b>${esc(name)}</b><small>${esc(mapCategoryName(m.categories[i]))}</small></span><span class="map-site-arrow">›</span></button>`).join('')||`<p class="map-empty">${esc(mapText('notFound'))}</p>`;
 if(madabaInteractiveMap) updateVisibleMarkers(filtered.map(x=>x.i));
}
function showMapSite(i){
 const m=window.MADABA_MAP_DATA,name=m.names[current][i],description=(m.descByLang?.[current]||m.descEn)[i];
 const el=$('#mapSiteDetails');el.hidden=false;
 el.innerHTML=`${m.images?.[i]?`<img class="map-detail-image" src="${m.images[i]}" alt="${esc(name)}" loading="lazy" referrerpolicy="no-referrer">`:''}<div class="map-detail-copy"><span class="section-kicker">${esc(mapText('details'))} · ${String(i+1).padStart(2,'0')}</span><h3>${esc(name)}</h3><p>${esc(description)}</p><small>${esc(mapText('source'))}</small><div class="map-detail-actions"><a class="btn btn-blue" href="${mapGoogleUrl(m.queries[i])}" target="_blank" rel="noopener">${esc(mapText('directions'))}</a><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(m.queries[i])}" target="_blank" rel="noopener">${esc(mapText('openMaps'))}</a></div></div>`;
 const marker=madabaMarkers.find(x=>x.index===i);if(marker&&madabaInteractiveMap){madabaInteractiveMap.setView(marker.marker.getLatLng(),Math.max(madabaInteractiveMap.getZoom(),15));marker.marker.openPopup();}
 el.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function updateVisibleMarkers(indices){madabaMarkers.forEach(({index,marker})=>{const show=indices.includes(index);if(show&&!madabaInteractiveMap.hasLayer(marker))marker.addTo(madabaInteractiveMap);if(!show&&madabaInteractiveMap.hasLayer(marker))madabaInteractiveMap.removeLayer(marker);});}
async function geocodeSite(i){
 if(mapLocationsCache[i])return mapLocationsCache[i];
 const key='madaba-map-geocode-v1-'+i;try{const saved=localStorage.getItem(key);if(saved){const v=JSON.parse(saved);mapLocationsCache[i]=v;return v;}}catch(e){}
 const query=window.MADABA_MAP_DATA.queries[i];
 try{const url='https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&country=Jordan&q='+encodeURIComponent(query);
 const response=await fetch(url,{headers:{'Accept-Language':'en'}});if(!response.ok)throw new Error('geocoder');const results=await response.json();
 if(results&&results[0]){const v=[Number(results[0].lat),Number(results[0].lon)];mapLocationsCache[i]=v;try{localStorage.setItem(key,JSON.stringify(v));}catch(e){}return v;}
 }catch(e){/* keep site available in the list and Google Maps links */}
 return null;
}
async function loadMapMarkers(){
 const m=window.MADABA_MAP_DATA;$('#mapSiteCount').textContent=mapText('loading');
 for(let i=0;i<m.names.en.length;i++){
  if(!madabaInteractiveMap)return;
  const coords=await geocodeSite(i);
  if(coords){const marker=L.marker(coords).bindPopup(`<strong>${esc(m.names[current][i])}</strong><br><a href="${mapGoogleUrl(m.queries[i])}" target="_blank" rel="noopener">${esc(mapText('directions'))}</a>`);marker.on('click',()=>showMapSite(i));marker.addTo(madabaInteractiveMap);madabaMarkers.push({index:i,marker});}
  if(i<m.names.en.length-1)await new Promise(r=>setTimeout(r,1050));
 }
 renderMapSiteList();
 const located=madabaMarkers.map(x=>x.marker.getLatLng());if(located.length>1){madabaInteractiveMap.fitBounds(L.latLngBounds(located).pad(0.12),{maxZoom:13});}
}
function initMaps(){
 if(!window.L)return;
 const center=[31.7167,35.7938];
 const mapEl=document.getElementById('madabaMap');if(!mapEl||madabaInteractiveMap)return;
 madabaInteractiveMap=L.map('madabaMap').setView(center,11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(madabaInteractiveMap);
 setTimeout(()=>madabaInteractiveMap.invalidateSize(),100);loadMapMarkers();
}
